func:
const raw = msg.payload || {};
const clean = v => String(v ?? '').trim().replace(/\s+/g,' ');
const normEmail = v => clean(v).toLowerCase();
const normPhone = (v, cc='') => {
  const rawPhone=clean(v); if(!rawPhone) return '';
  const digits=rawPhone.replace(/\D/g,'');
  if(rawPhone.startsWith('+')) return '+'+digits;
  const country=String(cc||'').replace(/\D/g,'');
  return country ? '+'+country+digits : digits;
};
const cc = msg.req && msg.req.headers ? (msg.req.headers['x-nexia-country-code'] || '') : '';
const lead={event_id:clean(raw.event_id),source:clean(raw.source).toLowerCase(),name:clean(raw.name),email:normEmail(raw.email),phone:normPhone(raw.phone,cc),service:clean(raw.service),message:clean(raw.message)};
const errors=[];
if(!lead.event_id) errors.push('missing_event_id');
if(!lead.source) errors.push('missing_source');
if(!lead.name) errors.push('missing_name');
if(!lead.email && !lead.phone) errors.push('missing_contact_method');
if(lead.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email)) errors.push('invalid_email');
if(lead.phone && lead.phone.replace(/\D/g,'').length<7) errors.push('invalid_phone');
let store=flow.get('nexiaStore') || {records:{},identityIndex:{},processedEvents:{},audit:[]};
const respond=(code,payload)=>{msg.statusCode=code;msg.headers={'content-type':'application/json'};msg.payload=payload;return msg;};
if(errors.length) return respond(422,{status:'validation_failed',category:'human_review',committed:false,errors,failure_alert:{event_id:lead.event_id||null,stage:'validation',reason:errors.join(','),action:'manual_review_required'}});
if(store.processedEvents[lead.event_id]) return respond(200,{status:'idempotent_skip',category:'duplicate_event',committed:false,event_id:lead.event_id});
const identities=[]; if(lead.email) identities.push('email:'+lead.email); if(lead.phone) identities.push('phone:'+lead.phone);
let recordId=null; for(const id of identities){if(store.identityIndex[id]){recordId=store.identityIndex[id];break;}}
let operation='created', preserved=[], filled=[];
if(recordId){operation='updated_existing'; const ex=store.records[recordId]; for(const f of ['name','email','phone','service','message','source']){const incoming=lead[f];if(!incoming)continue;if(!ex[f]){ex[f]=incoming;filled.push(f);}else if(ex[f]!==incoming){preserved.push(f);}}}
else {recordId='lead_'+String(Object.keys(store.records).length+1).padStart(4,'0');store.records[recordId]={id:recordId,...lead};}
for(const id of identities) store.identityIndex[id]=recordId;
store.processedEvents[lead.event_id]=true;
store.audit.push({event_id:lead.event_id,record_id:recordId,operation});
flow.set('nexiaStore',store);
return respond(200,{status:'processed',category:operation,committed:true,record_id:recordId,merge:{preserved,filled},internal_notification:{type:'new_or_updated_lead',record_id:recordId,source:lead.source,service:lead.service||'not_provided'},acknowledgement_draft:`Gracias, ${lead.name}. Hemos recibido tu solicitud${lead.service ? ' sobre '+lead.service : ''}. Este mensaje es un borrador y no se ha enviado.`});
